1: // Fly control from the worker. The org admin token (env.FLY_API_TOKEN) never
2: // leaves this process; the CLI only ever receives 1h app-scoped deploy tokens.
3: // Chosen over building from a tarball here: Fly has no build-from-tarball REST
4: // endpoint — remote builds speak the Docker/BuildKit protocol to a builder
5: // machine, which a Worker cannot. See docs/v3.
6: const MACHINES = 'https://api.machines.dev/v1';
7: const GQL = 'https://api.fly.io/graphql';
8: 
9: // Two credentials: FLY_ORG_TOKEN (long-lived org token) for app/IP/machine ops,
10: // FLY_API_TOKEN (short-lived user token) only for minting limited tokens —
11: // Fly rejects createLimitedAccessToken from org tokens (verified both dashboard-
12: // and flyctl-created). ponytail: user token's discharge expires in <1h, so
13: // minting (and thus deploys) needs a fresh one; offline macaroon attenuation of
14: // the org token would remove that — v4.
15: const authH = (token) => (token.startsWith('FlyV1') ? token : `Bearer ${token}`);
16: const machineToken = (env) => env.FLY_ORG_TOKEN || env.FLY_API_TOKEN;
17: 
18: async function gql(token, query, variables) {
19:   const resp = await fetch(GQL, {
20:     method: 'POST',
21:     headers: { Authorization: authH(token), 'Content-Type': 'application/json' },
22:     body: JSON.stringify({ query, variables }),
23:   });
24:   const body = await resp.json();
25:   if (body.errors) throw new Error(`fly graphql: ${body.errors[0].message}`);
26:   return body.data;
27: }
28: 
29: // Create the Fly app + shared IPv4. Idempotent — rerun on every deploy.
30: export async function ensureFlyApp(env, flyApp) {
31:   const resp = await fetch(`${MACHINES}/apps`, {
32:     method: 'POST',
33:     headers: { Authorization: authH(machineToken(env)), 'Content-Type': 'application/json' },
34:     body: JSON.stringify({ app_name: flyApp, org_slug: env.FLY_ORG_SLUG || 'personal' }),
35:   });
36:   if (!resp.ok) {
37:     const text = await resp.text();
38:     if (!/taken|already/i.test(text)) throw new Error(`fly app create failed (${resp.status}): ${text}`);
39:   }
40:   await gql(machineToken(env), 'mutation($app: ID!) { allocateIpAddress(input: {appId: $app, type: shared_v4}) { app { name } } }', { app: flyApp });
41: }
42: 
43: // One volume per app, named "data" — [storage] in small.toml. Idempotent: reuse
44: // the existing volume (and its region) on redeploy. Volume and machine must share
45: // a region, so the caller pins the machine to the returned region.
46: // ponytail: single volume, single region; per-region volumes when multi-machine matters.
47: export async function ensureVolume(env, flyApp, sizeGb) {
48:   const headers = { Authorization: authH(machineToken(env)), 'Content-Type': 'application/json' };
49:   const list = await fetch(`${MACHINES}/apps/${flyApp}/volumes`, { headers });
50:   if (!list.ok) throw new Error(`fly volumes list failed (${list.status}): ${await list.text()}`);
51:   const existing = (await list.json()).find((v) => v.name === 'data');
52:   if (existing) return existing.region;
53:   // an app deployed before [storage] already has machines somewhere — put the volume with them
54:   let region = env.FLY_VOLUME_REGION || 'iad';
55:   const machines = await fetch(`${MACHINES}/apps/${flyApp}/machines`, { headers });
56:   if (machines.ok) {
57:     const ms = await machines.json();
58:     if (ms.length) region = ms[0].region;
59:   }
60:   const resp = await fetch(`${MACHINES}/apps/${flyApp}/volumes`, {
61:     method: 'POST',
62:     headers,
63:     body: JSON.stringify({ name: 'data', region, size_gb: sizeGb }),
64:   });
65:   if (!resp.ok) throw new Error(`fly volume create failed (${resp.status}): ${await resp.text()}`);
66:   return (await resp.json()).region;
67: }
68: 
69: let orgIdCache;
70: async function orgId(env) {
71:   if (env.FLY_ORG_ID) return env.FLY_ORG_ID; // pinned: skips a flaky orgs query on the aging user token
72:   if (!orgIdCache) {
73:     const { organizations } = await gql(env.FLY_API_TOKEN, 'query { organizations { nodes { id slug type } } }');
74:     const nodes = organizations.nodes.filter(Boolean);
75:     const slug = env.FLY_ORG_SLUG || 'personal';
76:     const node = nodes.find((n) => n.slug === slug) || nodes.find((n) => n.type === 'PERSONAL');
77:     if (!node) throw new Error(`no fly org matching ${slug}`);
78:     orgIdCache = node.id;
79:   }
80:   return orgIdCache;
81: }
82: 
83: // Start one machine for a job run. auto_destroy + restart "no": the machine
84: // runs the image's CMD to completion and Fly removes it.
85: export async function startMachine(env, flyApp, config) {
86:   const resp = await fetch(`${MACHINES}/apps/${flyApp}/machines`, {
87:     method: 'POST',
88:     headers: { Authorization: authH(machineToken(env)), 'Content-Type': 'application/json' },
89:     body: JSON.stringify({ config }),
90:   });
91:   if (!resp.ok) throw new Error(`fly machine start failed (${resp.status}): ${await resp.text()}`);
92:   return resp.json();
93: }
94: 
95: // The only Fly credential the CLI ever sees: deploy-scoped to one app.
96: // Minting requires the user token — org tokens get UNAUTHORIZED here — and user
97: // tokens' org authorization rots ~30min after `flyctl auth token`. So each app's
98: // token is minted ONCE at app creation (30 days) and stored in D1; deploys of
99: // existing apps never touch the user token again. ponytail: stored token = one
100: // app's creds at rest for 30d; offline macaroon attenuation of the org token
101: // (superfly/macaroon has no JS port yet) replaces this in v4.
102: export async function mintDeployToken(env, flyApp) {
103:   const data = await gql(
104:     env.FLY_API_TOKEN,
105:     'mutation($input: CreateLimitedAccessTokenInput!) { createLimitedAccessToken(input: $input) { limitedAccessToken { tokenHeader } } }',
106:     { input: { name: `small-${flyApp}`, organizationId: await orgId(env), profile: 'deploy', profileParams: { app_id: flyApp }, expiry: '720h0m0s' } }
107:   );
108:   return data.createLimitedAccessToken.limitedAccessToken.tokenHeader;
109: }
110: 
111: // Stored-token accessor: serve from D1, mint+store on miss.
112: export async function deployTokenFor(env, app) {
113:   if (app.deploy_token) return app.deploy_token;
114:   const token = await mintDeployToken(env, app.fly_app);
115:   await env.DB.prepare('UPDATE apps SET deploy_token = ? WHERE id = ?').bind(token, app.id).run();
116:   return token;
117: }

