1: 'use strict';
2: const fs = require('fs');
3: const path = require('path');
4: const { detect } = require('./detect');
5: 
6: // os.environ["X"], os.environ.get("X"), os.getenv("X")
7: const ENV_RE = /os\.environ\[\s*["']([A-Za-z_]\w*)["']\s*\]|os\.(?:getenv|environ\.get)\(\s*["']([A-Za-z_]\w*)["']/g;
8: 
9: // Write small.toml from detection. Returns false when the entry could not be determined.
10: function init(dir, { force = false } = {}) {
11:   const tomlPath = path.join(dir, 'small.toml');
12:   if (fs.existsSync(tomlPath) && !force) {
13:     console.log('small.toml already exists — use --force to overwrite');
14:     return true;
15:   }
16: 
17:   let app = null;
18:   try {
19:     app = detect(dir);
20:   } catch {}
21:   const name = (app && app.name) || path.basename(dir).toLowerCase().replace(/[^a-z0-9-]/g, '-');
22:   const required = [];
23:   let source = '';
24:   if (app) {
25:     source = fs.readFileSync(path.join(dir, app.entry), 'utf8');
26:     for (const m of source.matchAll(ENV_RE)) {
27:       const v = m[1] || m[2];
28:       if (v.startsWith('SMALL_')) continue; // platform-injected (SMALL_DATA etc.), never a secret
29:       if (!required.includes(v)) required.push(v);
30:     }
31:   }
32:   const wantsStorage = /^\s*(?:import|from)\s+sqlite3\b/m.test(source) || source.includes('SMALL_DATA');
33:   const hasReqs = fs.existsSync(path.join(dir, 'requirements.txt'));
34: 
35:   const lines = [`name = "${name}"`];
36:   lines.push(app ? `entry = "${app.entry}"` : 'entry = ""                     # fill in: your app\'s main .py file');
37:   lines.push(`framework = "${app ? app.framework : ''}"`);
38:   if (hasReqs) lines.push('', '[deps]', 'file = "requirements.txt"');
39:   lines.push('', '[secrets]');
40:   lines.push(required.length ? `required = [${required.map((n) => `"${n}"`).join(', ')}]` : 'required = []                  # env vars this app reads — fill in');
41:   if (wantsStorage) lines.push('', '[storage]', 'path = "/data"', 'size = "1GB"');
42:   lines.push('', '[access]', 'visibility = "domain"', '');
43:   fs.writeFileSync(tomlPath, lines.join('\n'));
44: 
45:   console.log(`✓ name: ${name}`);
46:   if (app) console.log(`✓ entry: ${app.entry} (${app.framework})`);
47:   if (hasReqs) console.log('✓ deps: requirements.txt');
48:   if (required.length) console.log(`✓ secrets: ${required.join(', ')} (read by ${app.entry})`);
49:   if (wantsStorage) console.log('✓ storage: /data (1GB)');
50:   console.log('✓ visibility: domain');
51:   console.log('✓ wrote small.toml');
52:   if (!app) console.log('✗ could not find the entry file — fill in entry = "your-app.py" in small.toml');
53:   return !!app;
54: }
55: 
56: module.exports = { init };

