1: 'use strict';
2: const fs = require('fs');
3: const path = require('path');
4: 
5: function runCommand(entry, framework) {
6:   const mod = path.basename(entry, '.py');
7:   switch (framework) {
8:     case 'flask':
9:       return `gunicorn --bind 0.0.0.0:$PORT --timeout 300 ${mod}:app`;
10:     case 'fastapi':
11:       return `uvicorn ${mod}:app --host 0.0.0.0 --port $PORT`;
12:     case 'streamlit':
13:       return `streamlit run ${entry} --server.port $PORT --server.address 0.0.0.0 --server.headless true`;
14:     case 'gradio':
15:       // gradio reads these env vars in launch(); overrides any hardcoded defaults
16:       return `GRADIO_SERVER_NAME=0.0.0.0 GRADIO_SERVER_PORT=$PORT python ${entry}`;
17:     default:
18:       return `python ${entry}`;
19:   }
20: }
21: 
22: function runtimeSource(name) {
23:   const shipped = path.join(__dirname, '..', 'assets', name);
24:   if (fs.existsSync(shipped)) return shipped; // published package
25:   return path.join(__dirname, '..', '..', 'runtime', name); // monorepo dev
26: }
27: 
28: function dockerfile(app, dir) {
29:   const deps = (app.config.deps && app.config.deps.file) || 'requirements.txt';
30:   const system = app.config.system || (app.config.deps && app.config.deps.system) || [];
31:   const lines = ['FROM python:3.13-slim', 'WORKDIR /app'];
32:   if (system.length) {
33:     lines.push(`RUN apt-get update && apt-get install -y --no-install-recommends ${system.join(' ')} && rm -rf /var/lib/apt/lists/*`);
34:   }
35:   if (fs.existsSync(path.join(dir, deps))) {
36:     lines.push(`COPY ${deps} .`, `RUN pip install --no-cache-dir -r ${deps}`);
37:   }
38:   if (app.config.kind === 'job') {
39:     // no port, no guard: runner.py streams output to the control plane and exits
40:     lines.push(
41:       'COPY . .',
42:       'ENV PYTHONUNBUFFERED=1',
43:       `CMD ["python", ".small/runner.py", "sh", "-c", "${runCommand(app.entry, app.framework)}"]`
44:     );
45:   } else {
46:     lines.push(
47:       'COPY . .',
48:       'ENV PORT=8080',
49:       'ENV SMALL_APP_PORT=8090',
50:       'EXPOSE 8080',
51:       `CMD ["python", ".small/guard.py", "sh", "-c", "${runCommand(app.entry, app.framework)}"]`
52:     );
53:   }
54:   return lines.join('\n') + '\n';
55: }
56: 
57: // Writes .small/Dockerfile + .small/guard.py (or runner.py for jobs); ensures .env never enters the image.
58: function write(dir, app) {
59:   const out = path.join(dir, '.small');
60:   fs.mkdirSync(out, { recursive: true });
61:   fs.writeFileSync(path.join(out, 'Dockerfile'), dockerfile(app, dir));
62:   const py = app.config.kind === 'job' ? 'runner.py' : 'guard.py';
63:   fs.copyFileSync(runtimeSource(py), path.join(out, py));
64:   const ignorePath = path.join(dir, '.dockerignore');
65:   if (!fs.existsSync(ignorePath)) {
66:     fs.writeFileSync(ignorePath, '.env\n.git\n');
67:   } else if (!fs.readFileSync(ignorePath, 'utf8').split(/\r?\n/).includes('.env')) {
68:     console.error('! .dockerignore exists but does not exclude .env — secrets could end up in the image');
69:   }
70:   return out;
71: }
72: 
73: function writeFlyToml(dir, flyApp, memory, storage) {
74:   const lines = [`app = "${flyApp}"`];
75:   // volumes are per-region: pin the machine to the region the control plane put the volume in
76:   if (storage) lines.push(`primary_region = "${storage.region}"`);
77:   lines.push(
78:     '',
79:     '[http_service]',
80:     '  internal_port = 8080',
81:     '  force_https = true',
82:     '  auto_stop_machines = "stop"',
83:     '  auto_start_machines = true',
84:     '  min_machines_running = 0',
85:     ''
86:   );
87:   if (storage) {
88:     lines.push('[env]', `  SMALL_DATA = "${storage.path}"`, '', '[mounts]', '  source = "data"', `  destination = "${storage.path}"`, '');
89:   }
90:   lines.push('[[vm]]', '  size = "shared-cpu-1x"', `  memory = "${String(memory || '256mb').toLowerCase()}"`, '');
91:   fs.writeFileSync(path.join(dir, '.small', 'fly.toml'), lines.join('\n'));
92: }
93: 
94: module.exports = { runCommand, dockerfile, write, writeFlyToml };

